<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { api, getData } from '@/api'; import type { Item } from '@/types'; import { typeText, categoryText, statusText, formatTime } from '@/utils/labels'; import { useAuthStore } from '@/stores/auth'; import { ElMessage, ElMessageBox } from 'element-plus'
const route = useRoute(); const router = useRouter(); const auth = useAuthStore(); const item = ref<Item>(); const loading = ref(true)
onMounted(async () => { try { item.value = await getData(api.get(`/items/public/${route.params.id}`)) } finally { loading.value = false } })
async function claim() { if (!auth.loggedIn) return router.push({ name: 'login', query: { redirect: route.fullPath } }); const { value } = await ElMessageBox.prompt('请填写能够证明物品归属或识别物品的信息', '申请认领', { inputType: 'textarea', confirmButtonText: '提交申请', cancelButtonText: '取消', inputValidator: (v) => !!v.trim() || '认领证明不能为空' }); await api.post(`/claims/item/${route.params.id}`, { proof: value }); ElMessage.success('认领申请已提交') }
</script>
<template><section v-loading="loading" class="detail-page" v-if="item"><div class="detail-image" :style="item.imageUrl ? { backgroundImage: `url(${item.imageUrl})` } : {}"><span v-if="!item.imageUrl">{{ item.postType === 'LOST' ? '寻' : '招' }}</span></div><article class="detail-paper"><div class="tag-row"><el-tag :type="item.postType === 'LOST' ? 'danger' : 'success'">{{ typeText[item.postType] }}</el-tag><el-tag type="info">{{ categoryText[item.category] }}</el-tag><el-tag>{{ statusText[item.status] }}</el-tag></div><h1>{{ item.title }}</h1><div class="meta-grid"><div><small>发生地点</small><b>{{ item.location }}</b></div><div><small>发生时间</small><b>{{ formatTime(item.occurredAt) }}</b></div><div><small>发布者</small><b>{{ item.publisherName }}</b></div><div><small>联系方式</small><b>{{ item.contact }}</b></div></div><h3>物品描述</h3><p class="description">{{ item.description }}</p><el-button v-if="item.status === 'SEARCHING' && auth.user?.id !== item.publisherId" type="primary" size="large" @click="claim">我可能是物品主人</el-button></article></section></template>
